// ─── Monta o prompt de atualização do rolling_summary ────────────────────
// Recupera contexto: memória carregada + lote de novas mensagens

// A origem da memória pode vir do branch 'Record Exists? true' ou do 'Set Default Memory'
const trigger    = $('Execute Workflow Trigger').first().json;
const memBranch  = $input.first().json; // dados do nó Merge (o que passou)

// Garante fallback para strings vazias
const metaSummary    = (memBranch.meta_summary    || '').trim();
const rollingSummary = (memBranch.rolling_summary || '').trim();
const summaryVersion = Number(memBranch.summary_version || 0);

// Formata as novas mensagens do lote
const batch = trigger.messages_batch || [];
const formattedMessages = batch
  .map(m => {
    const speaker = m.role === 'assistant' ? 'Assistente' : 'Usuário';
    return `${speaker}: ${m.text}`;
  })
  .join('\n');

// ─── SYSTEM PROMPT ────────────────────────────────────────────────────────
const systemPrompt = `Você é a memória de longo prazo de uma conversa 1‑1 no WhatsApp.
Sua função é manter um resumo atualizado, conciso e objetivo do histórico.
Escreva sempre em terceira pessoa ("O usuário...", "O assistente...").
Preserve decisões tomadas, preferências, objetivos e problemas em aberto.
Elimie redundâncias, detalhes supérfluos e informações obsoletas.
Não ultrapasse 400 palavras no resumo incremental.`;

// ─── USER PROMPT ──────────────────────────────────────────────────────────
let userPrompt = '';

if (metaSummary) {
  userPrompt += `## Meta-resumo (contexto estável de longo prazo)\n${metaSummary}\n\n`;
}

if (rollingSummary) {
  userPrompt += `## Resumo incremental atual\n${rollingSummary}\n\n`;
} else {
  userPrompt += `## Resumo incremental atual\n(sem histórico ainda)\n\n`;
}

userPrompt += `## Novas mensagens desta janela\n${formattedMessages}\n\n`;
userPrompt += `## Tarefa\nAtualize o resumo incremental incorporando as novas mensagens acima.
Mantenha o resultado abaixo de 400 palavras. Retorne SOMENTE o resumo atualizado, sem explicações.`;

return [{
  json: {
    // dados de controle passados adiante
    chat_id         : trigger.chat_id,
    provider        : trigger.provider,
    myTs            : trigger.myTs,
    messages_batch  : batch,
    meta_summary    : metaSummary,
    rolling_summary : rollingSummary,
    summary_version : summaryVersion,
    // prompts para o LLM
    system_prompt   : systemPrompt,
    user_prompt     : userPrompt
  }
}];

