// Extrai o texto do rolling_summary gerado pelo LLM
const llmResponse   = $json;
const newRollingSummary = llmResponse.choices?.[0]?.message?.content?.trim() || '';

// Recupera metadados do nó anterior na chain
const prev = $('Build Progressive Summary Prompt').first().json;

// PARAMETRIZÁVEL: limite em caracteres para disparar meta-resumo (~250 tokens ≈ 1000 chars)
const META_SUMMARY_CHAR_THRESHOLD = 1200;

return [{
  json: {
    ...prev,
    new_rolling_summary : newRollingSummary,
    needs_meta_summary  : newRollingSummary.length > META_SUMMARY_CHAR_THRESHOLD
  }
}];

// ─── Monta o prompt para comprimir rolling → meta-resumo ──────────────────
const d = $json;

const systemPrompt = `Você é a memória de longo prazo desta conversa 1‑1 no WhatsApp.
Seu trabalho é criar um meta-resumo estável que capture os pontos mais importantes
da conversa de forma duradoura. Escreva em terceira pessoa.
Seja extremamente conciso: máximo 200 palavras.
Foque em: identidade do usuário, preferências duradouras, decisões importantes, objetivos.
Não inclua detalhes de conversas pontuais.`;

let userPrompt = '';
if (d.meta_summary) {
  userPrompt += `## Meta-resumo anterior\n${d.meta_summary}\n\n`;
}
userPrompt += `## Resumo incremental a comprimir\n${d.new_rolling_summary}\n\n`;
userPrompt += `## Tarefa\nCombine o meta-resumo anterior (se existir) com o resumo incremental acima.
Gere um novo meta-resumo ainda mais conciso (máx 200 palavras).
Retorne SOMENTE o meta-resumo, sem explicações.`;

return [{
  json: {
    ...d,
    meta_system_prompt : systemPrompt,
    meta_user_prompt   : userPrompt
  }
}];

