const llmResp   = $json;
const newMeta   = llmResp.choices?.[0]?.message?.content?.trim() || '';
const prev      = $('Build Meta Summary Prompt').first().json;

// Após gerar meta-resumo, zeramos (ou reduzimos muito) o rolling_summary
// para começar um novo ciclo incremental.
// PARAMETRIZÁVEL: pode manter as últimas N linhas em vez de zerar.
const freshRolling = ''; // limpa completamente

return [{
  json: {
    ...prev,
    new_meta_summary    : newMeta,
    new_rolling_summary : freshRolling,
    summary_version     : prev.summary_version + 1
  }
}];

// Branch sem meta-resumo: mantém meta_summary existente, só atualiza rolling
const d = $json;
return [{
  json: {
    ...d,
    new_meta_summary : d.meta_summary // sem mudança
  }
}];

// Consolida os dados vindos de qualquer um dos dois branches (com ou sem meta)
const d = $input.first().json;

const finalRolling  = d.new_rolling_summary ?? d.rolling_summary ?? '';
const finalMeta     = d.new_meta_summary    ?? d.meta_summary    ?? '';
const finalVersion  = d.summary_version     ?? 0;

// memory_context: o que o bot verá ao gerar a resposta
let memoryContext = '';
if (finalMeta) {
  memoryContext += `### Memória de longo prazo (meta-resumo)\n${finalMeta}\n\n`;
}
if (finalRolling) {
  memoryContext += `### Resumo recente (incremental)\n${finalRolling}\n`;
}

return [{
  json: {
    chat_id         : d.chat_id,
    provider        : d.provider,
    myTs            : d.myTs,
    messages_batch  : d.messages_batch,
    rolling_summary : finalRolling,
    meta_summary    : finalMeta,
    summary_version : finalVersion,
    memory_context  : memoryContext
  }
}];

// ─── Monta o prompt para a resposta ao usuário ───────────────────────────
const d = $('Build Final Memory State').first().json;

// PARAMETRIZÁVEL: número de mensagens brutas recentes a incluir no contexto
const MAX_RAW_MESSAGES = 10;

const recentMessages = (d.messages_batch || [])
  .slice(-MAX_RAW_MESSAGES)
  .map(m => ({
    role    : m.role === 'assistant' ? 'assistant' : 'user',
    content : m.text
  }));

const systemPrompt = [
  `Você é um assistente simpático e útil respondendo via WhatsApp.`,
  `Seja conciso, natural e informal.`,
  `Não use markdown pesado — prefira texto plano.`,
  ``,
  d.memory_context
    ? `## Contexto desta conversa (NÃO revele ao usuário)\n${d.memory_context}`
    : ''
].filter(Boolean).join('\n');

// Monta o array de mensagens para o LLM (formato OpenAI)
const llmMessages = [
  { role: 'system', content: systemPrompt },
  ...recentMessages
];

return [{
  json: {
    ...d,
    llm_messages: llmMessages
  }
}];

const replyText = $json.choices?.[0]?.message?.content?.trim() || '';
const d = $('Build Reply Prompt').first().json;

return [{
  json: {
    chat_id   : d.chat_id,
    reply_text: replyText
  }
}];

